{ id = "citta_vecchia", strato = 0, x = 0.26, terreno = "pietra", nome = T("La città vecchia", "The old town"),
  ora = T("Vicoli stretti, lastricati lucidi, portici. Qui piove sempre: le grondaie traboccano, le finestre sono accese di giallo, un ombrello solo attraversa la piazza.",
