{ id = "strade_nebbia", strato = 0, x = 0.45, terreno = "ghiaia", nome = T("Le strade nella nebbia", "The roads in the fog"),
  ora = T("La strada di campagna di notte, e la nebbia così fitta che i fari ci sbattono contro. Un cane abbaia da una cascina che non vedi. Due luci arrivano, ti passano accanto, spariscono.",
          "The country road at night, and fog so thick the headlights bounce off it. A dog barks from a farmhouse you can't see. Two lights arrive, pass you, vanish."),
  allora = T("Tornavi a casa così, piano, con il finestrino appena abbassato per sentire. Le righe bianche, una alla volta, erano tutto il mondo.",
             "You drove home like that, slowly, the window down a crack to hear. The white lines, one at a time, were the whole world."),
  altro = { T("Hai saputo della figlia del tuo amico. Un incidente, una strada, una sera come le altre.", "You heard about your friend's daughter. An accident, a road, an evening like any other."),
    T("Piangere per qualcuno che non conoscevi bene non è strano. È voler bene.", "Crying for someone you didn't know well isn't strange. It is love.") },
  macro = { "nebbia", "notte", "lacrime" }, macro_def = { 0.7, 0.5, 0.2 },
