{ id = "finestre", strato = 0, x = 0.54, terreno = "pietra", nome = T("Le finestre accese", "The lit windows"),
  ora = T("Di fronte, cento finestre. In una qualcuno cucina, in un'altra qualcuno piange, in un'altra ballano.",
          "Across the way, a hundred windows. In one someone is cooking, in another someone is crying, in another they're dancing."),
